import { existsSync, readdirSync, statSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { defineConfig } from 'vite';

// A multi-page site: the website pages (generated by tools/build-site.ts)
// plus the game at /play/. Every index.html below becomes a page.
const root = import.meta.dirname;
const PAGE_DIRS = ['', 'play', 'about', 'get-involved', 'ships', 'roadmap', 'design', 'press', 'ideas', 'privacy', 'jobs', 'companies', 'submit', 'connect', 'ship-editor', 'review', 'ship-preview', 'shared-space', 'economy', 'callsign'];

function findPages(dir: string, out: Record<string, string>) {
  const full = join(root, dir);
  if (!existsSync(full)) return;
  if (existsSync(join(full, 'index.html'))) out[dir || 'home'] = resolve(full, 'index.html');
  if (dir === '') return; // don't walk the whole repo from the root
  for (const name of readdirSync(full)) {
    if (statSync(join(full, name)).isDirectory()) findPages(join(dir, name), out);
  }
}

const input: Record<string, string> = {};
for (const dir of PAGE_DIRS) findPages(dir, input);

export default defineConfig({
  // Older browsers too (a player on an old Mac couldn't buy food): syntax is brought down to these;
  // newer runtime calls (structuredClone, Array.at, Object.hasOwn) are kept out of the game's code.
  build: { target: ['es2020', 'safari14', 'chrome87', 'firefox78', 'edge88'], rollupOptions: { input } },
  // A numbered ship's papers, /ships/<ship>/<edition>/<no>/, are one page per edition: as vercel.json serves them.
  plugins: [
    {
      name: 'papers',
      configureServer(server) {
        server.middlewares.use((req, _res, next) => {
          const m = /^\/ships\/([\w-]+)\/([\w-]+)\/\d{3}\/?(\?.*)?$/.exec(req.url ?? '');
          if (m) req.url = `/ships/${m[1]}/${m[2]}/papers/index.html`;
          next();
        });
      },
    },
  ],
  // Helper agents work in copies of the repo under .claude/worktrees: don't run their tests twice.
  test: { exclude: ['**/node_modules/**', '**/.claude/**'] },
});
